    qollash: { kattalar: "Maintenance 0.125–0.25 mg/day (per renal function); dose individualised.", bolalar: "By weight, under strict monitoring" },
    chiqarish: "Tablets 0.25 mg; solution for injection 0.25 mg/mL"
