    nojoya: { "Oshqozon-ichak": "Yuqori doza — ko'ngil aynishi, diareya, qorin og'rig'i", "Buyrak": "Oksalat toshlari (uzoq yuqori doza)", "Boshqa": "Glyukoza/siydik testlariга xalaqit (yuqori doza)" },
