    nojoya: { "Нервная система": "Головная боль, головокружение", "ЖКТ": "Тошнота, тяжесть в эпигастрии", "Сосуды": "Гипотензия (быстрое в/в), покраснение лица", "Аллергические": "Сыпь (редко)" },
